async function generateSig(data, key) {
	const encoder = new TextEncoder();
	const encodedData = encoder.encode(data);
	const encodedKey = encoder.encode(key);

	const cryptoKey = await window.crypto.subtle.importKey(
		"raw",
		encodedKey,
		{ name: "HMAC", hash: "SHA-256" },
		false,
		["sign"]
	);
	
	const signature = await window.crypto.subtle.sign(
		"HMAC",
		cryptoKey,
		encodedData
	);

	// first 10 characters are used as a signature, its secure enough for this project's purpose
	return Array.from(new Uint8Array(signature))
		.map(b => b.toString(16).padStart(2, '0'))
		.join('')
		.substring(0, 5);
}

document.getElementById('qrForm').addEventListener('submit', async function (e) {
	e.preventDefault();
	
	const firstname = document.getElementById("firstnameInput").value;
	const surname = document.getElementById("surnameInput").value;
	const strand = document.getElementById("strandInput").value;
	const section = document.getElementById("sectionInput").value;
	const gradYear = document.getElementById("gradInput").value;
	
	const infoData = `KC${firstname}+${surname}+${gradYear}${strand}${section}`;
	console.log(infoData);
	
	document.getElementById("canvas").innerHTML = '';
	
	const signature = await generateSig(infoData, notsoSecretkey);
	const qrData = `${infoData}:${signature}`;
	console.log(qrData);
	
	options.data = qrData;
	const qrCode = new QRCodeStyling(options);
	qrCode.append(document.getElementById("canvas"));
	
	document.getElementById("copyButton").disabled =false;
	document.getElementById("downloadButton").disabled =false;
});

function canvasToBlob(){
	return new Promise((resolve) => {
		document.querySelector("#canvas canvas").toBlob(async (blob) => {
			resolve(blob)
		}, "image/png");
	});
};

document.getElementById("copyButton").addEventListener("click", async function() {
	const blob = await canvasToBlob();
	const item = new ClipboardItem({ "image/png": blob });
	await navigator.clipboard.write([item]);
	this.setAttribute("data-tooltip", "Copied!");
	setTimeout(() => this.removeAttribute("data-tooltip"), 1000);
});

document.getElementById("downloadButton").addEventListener("click", async function() {
	const blob = await canvasToBlob();
	const downloadUrl = URL.createObjectURL(blob);
	console.log(downloadUrl)
	
	const hiddenLink = document.createElement("a");
	hiddenLink.href = downloadUrl;
	hiddenLink.download = `${document.getElementById("surnameInput").value}, ${document.getElementById("firstnameInput").value} - ARGUS ID.png`
	hiddenLink.click();
	
	URL.revokeObjectURL(downloadUrl);
})